            // TODO API_TEST_START
            java.awt.Graphics2D g2d = destinationImage.createGraphics();
            g2d.setColor(java.awt.Color.MAGENTA);
            g2d.fillRect(0, 0, destinationImage.getWidth(), destinationImage.getHeight());
            g2d.dispose();

            int beforeColor = destinationImage.getRGB(0, 0);

            net.coobird.thumbnailator.resizers.Resizer resizer = new net.coobird.thumbnailator.resizers.ProgressiveBilinearResizer();
            resizer.resize(sourceImage, destinationImage);

            boolean changed = false;
