                for (int x = 0; x < destinationImage.getWidth(); x++) {
                    if (destinationImage.getRGB(x, y) != beforeColor) {
                        changed = true;
                        break;
                    }
                }
                if (changed) break;
            }

            assert changed : "Destination image was not modified by resize operation";
            System.out.println("__CHECK__ resize " + changed);
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
